DATA=$(cat my-work/ss-claim-62-vs-70-balances.json); cat > my-work/ss-claim-62-vs-70.html <<EOF
<!doctype html><html><head><meta charset="utf-8"><title>Portfolio balance: claim at 62 vs 70</title>
<style>
.viz-root{color-scheme:light;--surface-1:#fcfcfb;--text-primary:#0b0b0b;--text-secondary:#52514e;--text-muted:#7a7974;--grid:#e6e5e1;--axis:#bdbcb6;--s62:#2a78d6;--s70:#eb6834}
@media (prefers-color-scheme:dark){:root:where(:not([data-theme="light"])) .viz-root{color-scheme:dark;--surface-1:#1a1a19;--text-primary:#f0efec;--text-secondary:#c3c2b7;--text-muted:#8f8e86;--grid:#2c2c2a;--axis:#4a4a46;--s62:#3987e5;--s70:#d95926}}
:root[data-theme="dark"] .viz-root{color-scheme:dark;--surface-1:#1a1a19;--text-primary:#f0efec;--text-secondary:#c3c2b7;--text-muted:#8f8e86;--grid:#2c2c2a;--axis:#4a4a46;--s62:#3987e5;--s70:#d95926}
body{margin:0;background:var(--surface-1)}
.viz-root{background:var(--surface-1);color:var(--text-primary);font:14px/1.4 -apple-system,system-ui,sans-serif;padding:24px 32px;max-width:980px}
h1{font-size:19px;font-weight:600;margin:0 0 4px} h2{font-size:15px;font-weight:600;margin:28px 0 2px}
.sub{color:var(--text-secondary);margin:0 0 10px}
.legend{display:flex;gap:20px;color:var(--text-secondary);margin:6px 0 2px}
.legend span::before{content:"";display:inline-block;width:18px;height:2px;vertical-align:middle;margin-right:6px;background:var(--c)}
.legend .bar::before{height:10px;width:10px;border-radius:2px}
svg text{fill:var(--text-secondary);font-size:12px} .lbl{fill:var(--text-primary);font-weight:600}
.tip{position:fixed;pointer-events:none;background:var(--surface-1);border:1px solid var(--axis);border-radius:6px;padding:8px 10px;font-size:12.5px;box-shadow:0 2px 8px rgba(0,0,0,.15);display:none;white-space:nowrap}
.note{color:var(--text-muted);font-size:12.5px;margin-top:18px}
table{border-collapse:collapse;font-size:12.5px;margin-top:8px} td,th{padding:3px 10px;text-align:right;border-bottom:1px solid var(--grid)}
</style></head><body><div class="viz-root">
<h1>Portfolio balance: claim Social Security at 62 vs. 70</h1>
<p class="sub">Homer's retirement plan · end-of-year portfolio, deterministic middle path · <b>today's (2026) dollars</b></p>
<div class="legend"><span style="--c:var(--s62)">Claim at 62</span><span style="--c:var(--s70)">Claim at 70</span></div>
<svg id="c1" width="920" height="340"></svg>
<h2>How far ahead claiming at 62 is (gap between the two lines)</h2>
<p class="sub">Above zero: claiming at 62 has more invested. Below zero: claiming at 70 has more.</p>
<div class="legend"><span class="bar" style="--c:var(--s62)">62 ahead</span><span class="bar" style="--c:var(--s70)">70 ahead</span></div>
<svg id="c2" width="920" height="260"></svg>
<details><summary>Table view</summary><table id="tbl"></table></details>
<p class="note">Source: bin/engine-cli artifacts get forecast.balance-sheet.chart --dossier homer_s_retirement_plan --ss-claim-age {62|70} --death-age 95 --quiet (Tutilis 1.0.0, built-in catalog). Engine reports nominal dollars; converted to 2026 dollars at the plan's 2% inflation. A single middle path, not a range of outcomes.</p>
</div><div class="tip" id="tip"></div>
<script>
const raw=${DATA};
const rows=raw.map(([y,a,b62,b70])=>{const d=Math.pow(1.02,y-2026);return {y,a,v62:b62/d,v70:b70/d,gap:(b62-b70)/d}});
const fmt=v=>(v<0?"−":"")+"\$"+Math.round(Math.abs(v)).toLocaleString();
const fk=v=>(v<0?"−":"")+"\$"+(Math.abs(v)>=1e6?(Math.abs(v)/1e6).toFixed(1)+"M":Math.round(Math.abs(v)/1e3)+"k");
const NS="http://www.w3.org/2000/svg",css=getComputedStyle(document.querySelector('.viz-root'));
const el=(p,t,a)=>{const e=document.createElementNS(NS,t);for(const k in a)e.setAttribute(k,a[k]);p.appendChild(e);return e};
const tip=document.getElementById('tip');
function frame(svg,ymin,ymax,ticks){const W=+svg.getAttribute('width'),H=+svg.getAttribute('height'),m={l:64,r:90,t:14,b:34};
 const x=a=>m.l+(a-62)/(94-62)*(W-m.l-m.r), y=v=>m.t+(ymax-v)/(ymax-ymin)*(H-m.t-m.b);
 ticks.forEach(t=>{el(svg,'line',{x1:m.l,x2:W-m.r,y1:y(t),y2:y(t),stroke:t===0?'var(--axis)':'var(--grid)','stroke-width':1});el(svg,'text',{x:m.l-8,y:y(t)+4,'text-anchor':'end'}).textContent=fk(t)});
 for(let a=62;a<=94;a+=4){el(svg,'text',{x:x(a),y:H-m.b+18,'text-anchor':'middle'}).textContent=a}
 el(svg,'text',{x:W-m.r,y:H-4,'text-anchor':'end'}).textContent='Your age (end of year)';
 return {x,y,W,H,m}}
function marker(svg,f,a,label,top){const X=f.x(a);el(svg,'line',{x1:X,x2:X,y1:f.m.t,y2:f.H-f.m.b,stroke:'var(--axis)','stroke-dasharray':'3 3'});el(svg,'text',{x:X+5,y:f.m.t+(top||10)}).textContent=label}
function hover(svg,f,html){const g=el(svg,'g',{});const cross=el(g,'line',{y1:f.m.t,y2:f.H-f.m.b,stroke:'var(--text-muted)','stroke-width':1,visibility:'hidden'});
 const hit=el(svg,'rect',{x:f.m.l,y:f.m.t,width:f.W-f.m.l-f.m.r,height:f.H-f.m.t-f.m.b,fill:'transparent'});
 hit.addEventListener('mousemove',e=>{const r=svg.getBoundingClientRect();const a=Math.max(62,Math.min(94,Math.round(62+(e.clientX-r.left-f.m.l)/(f.W-f.m.l-f.m.r)*32)));const d=rows[a-62];
  cross.setAttribute('x1',f.x(a));cross.setAttribute('x2',f.x(a));cross.setAttribute('visibility','visible');tip.innerHTML=html(d);tip.style.display='block';tip.style.left=(e.clientX+14)+'px';tip.style.top=(e.clientY+14)+'px'});
 hit.addEventListener('mouseleave',()=>{tip.style.display='none';cross.setAttribute('visibility','hidden')})}
const sw=c=>'<span style="display:inline-block;width:10px;height:10px;border-radius:2px;background:var('+c+');margin-right:6px"></span>';
const tipHtml=d=>'<b>Age '+d.a+' ('+d.y+')</b><br>'+sw('--s62')+'Claim at 62: '+fmt(d.v62)+'<br>'+sw('--s70')+'Claim at 70: '+fmt(d.v70)+'<br>Gap: '+fmt(d.gap)+(d.gap>=0?' (62 ahead)':' (70 ahead)');
// chart 1
{const svg=document.getElementById('c1'),f=frame(svg,1.2e6,3.0e6,[1.2e6,1.6e6,2.0e6,2.4e6,2.8e6]);
 marker(svg,f,70,'Age 70: checks start if you wait');marker(svg,f,86,'Age 86: 70 catches up',26);
 [['v62','--s62'],['v70','--s70']].forEach(([k,c])=>{el(svg,'path',{d:rows.map((r,i)=>(i?'L':'M')+f.x(r.a)+','+f.y(r[k])).join(''),fill:'none',stroke:'var('+c+')','stroke-width':2,'stroke-linejoin':'round'})});
 const L=rows[rows.length-1];el(svg,'text',{x:f.x(94)+8,y:f.y(L.v70)-2,class:'lbl'}).textContent='70: '+fk(L.v70);el(svg,'text',{x:f.x(94)+8,y:f.y(L.v62)+12,class:'lbl'}).textContent='62: '+fk(L.v62);
 hover(svg,f,tipHtml)}
// chart 2
{const svg=document.getElementById('c2'),f=frame(svg,-150000,220000,[-100000,0,100000,200000]);
 const bw=(f.x(63)-f.x(62))-2;
 rows.forEach(r=>{const y0=f.y(0),y1=f.y(r.gap);el(svg,'rect',{x:f.x(r.a)-bw/2,y:Math.min(y0,y1),width:bw,height:Math.max(1,Math.abs(y1-y0)),rx:2,fill:r.gap>=0?'var(--s62)':'var(--s70)'})});
 const pk=rows[69-62];el(svg,'text',{x:f.x(69),y:f.y(pk.gap)-6,'text-anchor':'middle',class:'lbl'}).textContent='Peak at 69: '+fk(pk.gap);
 const L=rows[rows.length-1];el(svg,'text',{x:f.x(94)+8,y:f.y(L.gap)+4,class:'lbl'}).textContent=fk(L.gap);
 hover(svg,f,tipHtml)}
document.getElementById('tbl').innerHTML='<tr><th>Age</th><th>Year</th><th>Claim at 62</th><th>Claim at 70</th><th>Gap</th></tr>'+rows.map(r=>'<tr><td>'+r.a+'</td><td>'+r.y+'</td><td>'+fmt(r.v62)+'</td><td>'+fmt(r.v70)+'</td><td>'+fmt(r.gap)+'</td></tr>').join('');
</script></body></html>
EOF
